import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    H = [int(x) for x in data[1:1 + n]]
    # 1-indexed arrays; f[n+1] = 0 implicitly handled
    f = [0] * (n + 2)
    stack = []  # indices (1-based) with decreasing heights from bottom to top
    for k in range(n, 0, -1):
        h = H[k - 1]
        while stack and H[stack[-1] - 1] < h:
            stack.pop()
        if stack:
            f[k] = 1 + f[stack[-1]]
        else:
            f[k] = 1
        stack.append(k)
    res = []
    for i in range(1, n + 1):
        if i + 1 <= n:
            res.append(f[i + 1])
        else:
            res.append(0)
    print(" ".join(map(str, res)))

