def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    h = [0] * (n + 2)
    for i in range(n):
        h[i + 1] = int(data[1 + i])
    # dp[n+1] = 0 represents "no next greater"
    dp = [0] * (n + 2)
    stack = []
    for j in range(n, 0, -1):
        while stack and h[stack[-1]] < h[j]:
            stack.pop()
        nxt = stack[-1] if stack else n + 1
        dp[j] = 1 + dp[nxt] if nxt != n + 1 else 1
        stack.append(j)
    res = []
    for i in range(1, n + 1):
        if i == n:
            res.append(0)
        else:
            res.append(dp[i + 1])
    print(" ".join(map(str, res)))

